/* SPDX-License-Identifier: MPL-2.0 */

'use strict';

/**
 * Which RGAA tests each rule checks, per RGAA version.
 *
 * PURPOSE
 * -------
 * RGAA does not restate WCAG criterion by criterion (WCAG 1.1.1 alone relates
 * to 19 RGAA criteria), so a rule's RGAA tests cannot be derived from its WCAG
 * mapping the way an EN 301 549 clause is. They are stated here, rule by rule.
 *
 * THE MAPPING RULE
 * ----------------
 * A rule maps to a test when a failure of the rule (or, for a manual rule, the
 * question it raises) is direct evidence about what the test's official
 * methodology checks, on the same kind of element. Covering one step of a
 * multi-step test is enough; sharing a WCAG criterion, or a theme, is not.
 * A rule that checks presence maps to the presence test, a manual "quality"
 * rule to the relevance test. `note` says which step and why, for review.
 *
 * A rule that fails is linked to a test only when its usual failures really
 * fail that test. Where that is uncertain, the test is left off (when the
 * problem is already reported under a test it certainly fails) or the rule
 * asks (cantTell) instead of failing. A question is never a false failure, so
 * a manual rule may link to any test its question bears on.
 *
 * The build rejects an unknown rule id or test id, a field other than tests,
 * note and outsideCorrespondence, and a rule mapped to WCAG criteria none of
 * which RGAA relates to the test's criterion, unless outsideCorrespondence
 * says why (src/coverage/rgaa-mappings.js). A rule with no WCAG mapping may
 * map to any test: RGAA checks some things WCAG leaves to best practice, such
 * as heading hierarchy and landmarks.
 *
 * REVIEW STATUS: drafted from the RGAA 4.1.2 test wording and methodology
 * (scripts/data/rgaa/), then checked row by row against how other RGAA tools
 * map and flag the same checks. Not yet reviewed by an RGAA auditor.
 */

const RGAA_RULE_TESTS = {
  '4.1.2': {
    "accesskeys": { tests: [], note: "Asks for review of duplicate accesskey values across elements. 12.10.1 concerns single-key shortcuts without modifiers, and accesskey always uses a modifier. The Nu checker (8.2.1) does not treat the same accesskey on different elements as an error. No RGAA test checks this." },
    "area-alt-present": { tests: ["1.1.2"], note: "Fails an <area href> in a used image map that has no non-empty alt/aria-label/aria-labelledby/title, which is the presence check of 1.1.2 step 3 (a linked area is always informative). Partial: the rule also accepts title and aria-labelledby, which 1.1.2 does not list, so a pass is weaker evidence than a fail." },
    "area-alt-quality": { tests: ["1.3.2"], note: "Asks a human to judge the non-empty alt of a linked <area>, which is exactly 1.3.2 step 2 (relevance of the area's text alternative)." },
    "aria-allowed-attr": { tests: ["8.2.1"], note: "Fails when an aria-* attribute is neither global nor supported by the element's explicit role. That is an attribute not allowed on that element, which the Nu checker used in 8.2.1 reports as a markup error (attributes respecting writing rules). Not mapped to 7.1.1 (where other RGAA tools put this check): the rule also fires on static markup, which is not a scripted component." },
    "aria-allowed-role": { tests: ["8.2.1"], note: "Flags explicit roles that ARIA in HTML does not permit on the host element (for example role=tab on nav). The Nu checker applies ARIA in HTML and reports these as bad values for the role attribute, which is 8.2.1 step 2 (attribute values respect the writing rules). Whether the role is appropriate for the component (7.1.3) is a separate judgment that the rule does not make." },
    "aria-braille-equivalent": { tests: [], note: "Fails when aria-braillelabel is used without a regular accessible name, or aria-brailleroledescription without aria-roledescription, on any element. No RGAA test targets these ARIA 1.3 attributes. The missing-name case would only be evidence for 7.1.1 (explicit name) on a scripted component, which the rule does not identify. Reviewer may consider 8.2.1 if the validator flags it." },
    "aria-checked-state-mismatch": { tests: ["8.2.1"], note: "Flags native checkbox/radio inputs whose explicit aria-checked disagrees with their real state. ARIA in HTML forbids aria-checked on input type=checkbox and type=radio, and the Nu checker (26.9.27) reports it as an error in both cases, so every occurrence fails 8.2.1. Not mapped to 7.1.1 (where other RGAA tools put this check): a native input is not a scripted component." },
    "aria-conditional-attr": { tests: [], note: "Flags aria-errormessage without a non-false aria-invalid (reported as cantTell). A field can legitimately carry an inert aria-errormessage while no error is shown. 11.10.3/11.10.6 accept a visible message naming the field instead of aria-invalid, so this is not direct evidence for any RGAA test." },
    "aria-deprecated-role": { tests: [], note: "Flags roles that WAI-ARIA deprecates or reserves for user agents (e.g. generic). The spec only advises against these ('SHOULD NOT'); it does not make them invalid, so this is not a failed 8.2.1 validity condition. No other RGAA test covers the choice of role outside scripted components (7.1.3)." },
    "aria-hidden-body": { tests: ["10.8.1"], note: "Fails aria-hidden=\"true\" on <body>, which hides the whole page from AT. 10.8.1 step 1 lists aria-hidden elements as hidden content, and step 2 requires hidden content to be meant to be ignored, which the whole page never is." },
    "aria-hidden-focus": { tests: ["10.8.1"], note: "Fails when an aria-hidden=true element is focusable or contains focusable descendants. That is direct evidence for 10.8.1 step 2 on aria-hidden content: keyboard users can reach content hidden from assistive technology, so it is not content meant to be ignored, yet it is not made available to AT. Other candidates (images, frames, scripts) are not about this element-level condition." },
    "aria-prohibited-attr": { tests: ["8.2.1"], note: "Fails when aria-label/aria-labelledby is set on roles where ARIA prohibits naming (generic, paragraph, strong...). Since Nu 26.1.1 the checker reports this as an error, so it fails 8.2.1 (24.10.17 only warned about aria-label). Not mapped to 7.1.1 (where other RGAA tools put this check): the rule fires on plain div, span and p elements, which are not scripted components." },
    "aria-prohibited-children": { tests: ["9.3.1","9.3.2"], note: "Fails a container role that owns a child with a disallowed role. For role=\"list\", that means the items are not role=\"listitem\", which is the structure check of 9.3.1/9.3.2 step 2. For widget containers (listbox, menu, tablist, tree, radiogroup), it is evidence against 7.1.1 step 2 (roles consistent with use), a weaker, off-candidate link. Not mapped to 7.1.1: the widget-role link is indirect; the list tests are the direct match." },
    "aria-required-attr": { tests: ["8.2.1"], note: "Fails when an explicit role lacks a required state/property (e.g. role=checkbox without aria-checked). The Nu checker used in 8.2.1 reports this as a missing required attribute. Not mapped to 7.1.1 (where other RGAA tools put this check): its methodology steps (role, name, name consistent with state) do not check state attributes, and the rule also fires on elements no script drives." },
    "aria-required-children": { tests: ["9.3.1","9.3.2"], note: "Asks (cantTell) whether a container role owns none of its required child roles. For role=\"list\" with no role=\"listitem\" items, that is the 9.3.1/9.3.2 structure check. For widgets, it bears on 7.1.1 role consistency (off-candidate). Low because an empty container is not in itself a failure. Not mapped to 7.1.1: the widget-role link is indirect; the list tests are the direct match." },
    "aria-required-parent": { tests: ["9.3.1","9.3.2"], note: "Fails roles such as listitem, option, tab, menuitem, treeitem or row with no valid context parent. An orphan role=\"listitem\" means the list is not built from role=\"list\"+\"listitem\" (9.3.1/9.3.2 step 2). For widget items, it is evidence for 7.1.1 role consistency (off-candidate). The table roles (row/cell) are not mapped, because 5.6 only checks header declaration. Not mapped to 7.1.1: the widget-role link is indirect; the list tests are the direct match." },
    "aria-role-name-present": { tests: ["7.1.1","11.1.1","11.6.1"], note: "Fails when role grid, meter, progressbar, radiogroup or tree has no aria-label, aria-labelledby or title. For radiogroup, this is 11.6.1 step 2 (group has aria-label or aria-labelledby); for meter and progressbar, 11.1.1 (the RGAA glossary counts progressbar and meter as form fields); for grid and tree widgets, 7.1.1 step 2 (component has an explicit name), which no other test covers. 11.6.1 can still pass through per-field labels (step 3).", outsideCorrespondence: {"11.6.1":"For role=\"radiogroup\" only: 11.6.1 step 2 requires a radiogroup to have aria-label or aria-labelledby. RGAA relates 11.6 to WCAG 1.3.1 and 3.3.2, while the engine files naming under 4.1.2."} },
    "aria-roles-valid": { tests: ["8.2.1"], note: "Fails when an explicit role value is not a real, non-abstract WAI-ARIA role. The Nu checker used in 8.2.1 reports this as an invalid attribute value (attribute values respecting writing rules). Not mapped to 7.1.1 (where other RGAA tools put this check): the rule also fires on static markup, which is not a scripted component." },
    "aria-text": { tests: [], note: "Checks that role=\"text\" containers have no focusable descendants. role=\"text\" is a non-standard ARIA value and no RGAA test examines it or the focusability of its content; 7.1.1 concerns roles of scripted components, not this pattern." },
    "aria-valid-attr": { tests: ["8.2.1"], note: "Flags aria-* attribute names not defined by WAI-ARIA. 8.2.1 step 2 (Nu markup checker) requires attributes to respect the writing rules, and the checker reports undefined aria-* attributes as not allowed; the rule covers only that slice of the test. Not mapped to 7.1.1 (where other RGAA tools put this check): the rule also fires on static markup, which is not a scripted component." },
    "aria-valid-attr-value": { tests: ["8.2.1"], note: "Flags recognized aria-* attributes whose value does not match the declared type (boolean, token, integer, idref that does not resolve). 8.2.1 step 2 requires attribute values to respect the writing rules, and the Nu checker reports bad ARIA values as errors. A dangling ID reference is no longer a validator error (since Nu 26.5.6), except for aria-activedescendant. Covers part of that step only. Not mapped to 7.1.1 (where other RGAA tools put this check): the rule also fires on static markup, which is not a scripted component." },
    "autocomplete-valid": { tests: ["8.2.1","11.13.1"], note: "Fails a non-empty autocomplete value that is not on/off or a well-formed autofill token list. That covers the 11.13.1 step-2 condition that the value is in the list of allowed values; it does not check that the attribute is present or relevant. A malformed value is also a bad attribute value under 8.2.1 (secondary).", outsideCorrespondence: {"8.2.1":"RGAA relates 8.2 to WCAG 4.1.1 and 4.1.2; the engine files this rule under another criterion because WCAG 2.2 removed 4.1.1 (Parsing). A malformed autocomplete value breaks 8.2.1's condition \"Les balises, attributs et valeurs d’attributs respectent les règles d’écriture\"."} },
    "avoid-inline-spacing": { tests: ["10.12.1"], note: "Fails text whose inline style forces line-height, letter-spacing or word-spacing with !important below the WCAG 1.4.12 values. That setting defeats the style override in 10.12.1 step 1, so the text cannot receive the required spacing. The rule does not check the readability or loss of content of step 2." },
    "binary-control-name-present": { tests: ["11.1.1"], note: "Checks that elements with explicit role checkbox/radio/switch have a name from aria-labelledby, aria-label, title or an associated label: the same mechanisms 11.1.1 step 2 lists for form fields (RGAA counts ARIA checkbox/radio/switch as form fields, and other RGAA tools use 11.1.1 too). Not mapped to 7.1.1 (where other RGAA tools put this check): 7.1.1 passes when an accessible alternative exists, so a failure under it is not certain, and the problem is already reported under 11.1.1." },
    "button-name-present": { tests: ["11.9.1"], note: "Flags button, input button/submit/reset and role=button with an empty accessible name. An empty name fails 11.9.1 step 2 (visible label and accessible name relevant), where other RGAA tools put the check too; strictly, 11.9 covers buttons inside a form. Not mapped to 7.1.1: it passes when an accessible alternative exists, so a failure under it is not certain." },
    "bypass-blocks-present": { tests: ["12.6.1","12.7.1"], note: "Raises a review question only when the page has no exposed <main>/role=main, no working same-page anchor link and no visible heading, i.e. the main content zone has none of the 12.6.1 step-2 mechanisms (landmark, heading, skip/quick-access link) and 12.7.1 step 2 finds no skip or quick-access link to it. A clean result does not cover 12.7.1, since a main landmark alone silences the rule." },
    "canvas-text-alternative-present": { tests: ["1.1.8"], note: "Fails a <canvas> with neither fallback content nor an accessible name, i.e. none of the alternatives of 1.1.8 steps 4 and 6. Partial: it does not check the role=\"img\" requirement (step 3), the adjacent-link/replacement options, or whether the canvas is informative." },
    "canvas-text-alternative-quality": { tests: ["1.3.7"], note: "Asks a human to judge the relevance of a canvas's existing name or fallback content, which is 1.3.7 step 2. It does not ask whether AT actually renders the fallback, so not 1.3.8." },
    "combobox-name-present": { tests: ["11.1.1"], note: "Checks that role=combobox has a name from aria-label, aria-labelledby, title or an associated label, which matches the conditions in 11.1.1 step 2 for form fields (combobox is an ARIA form-field role, and other RGAA tools use 11.1.1 too). Not mapped to 7.1.1: it passes when an accessible alternative exists, and the problem is already reported under 11.1.1." },
    "complex-table-summary": { tests: ["5.1.1"], note: "Asks whether a summary is available for a table the rule takes as complex: a header cell outside both the first row and the first column, or a cell with a headers attribute, as in RGAA's definition of a complex data table. A table with aria-describedby or a summary attribute is not asked about. The summary may sit in the caption or next to the table, which only a person can judge." },
    "contrast-computable": { tests: ["3.2.1","3.2.2","3.2.3","3.2.4"], note: "Returns cantTell for visible text whose contrast cannot be computed (background image or gradient, blend mode, filter, text-shadow, opacity). This marks the text that 3.2.1 to 3.2.4 step 1 must find and measure by hand; it never gives a verdict. It does not check the paired CSS color declarations of 10.5, so 10.5 is not mapped." },
    "contrast-enhanced": { tests: [], note: "AAA check (7:1 / 4.5:1). RGAA has no enhanced-contrast test, and failing 7:1 says nothing about the 4.5:1 / 3:1 thresholds of 3.2.x (contrast-minimum covers those)." },
    "contrast-minimum": { tests: ["3.2.1","3.2.2","3.2.3","3.2.4"], note: "Fails computable text below 4.5:1 (normal) or 3:1 (large), which is 3.2.1 to 3.2.4 step 2. Caveats: bold text counts as large from about 18.67px here versus 18.5px in RGAA, so bold text between 18.5 and 18.67px is held to 4.5:1 instead of 3:1; and it does not consider an alternative contrast mechanism." },
    "css-focus-indicator-suppressed": { tests: ["10.7.1"], note: "Flags tab-order elements whose outline is removed by a :focus/:focus-visible rule, with no border, box-shadow or background replacement in any matching focus rule. That is 10.7.1 condition 1 (native focus style removed) and step 2 (visual focus indicator present). The 3:1 contrast part of step 2 is not checked." },
    "css-hidden-focus": { tests: ["10.7.1"], note: "Flags keyboard-focusable elements that are visually hidden (opacity 0, clipped, off-screen, zero-size with overflow hidden), so taking focus on them gives no visible indication. This is evidence for 10.7.1 step 2 on focusable elements. It is not 10.8.1, because the content stays exposed to AT and the problem is purely visual." },
    "css-orientation-lock": { tests: ["13.9.1"], note: "Fails an @media (orientation) block that rotates the page by about 90 degrees, a known way to force one orientation. That is direct evidence that viewing is not possible in both portrait and landscape (13.9.1 step 2). The essential-orientation exception still needs a human." },
    "definition-list-children-valid": { tests: ["8.2.1","9.3.3"], note: "Fails a <dl> whose children are not dt/dd groups (one wrapping div allowed) or have an unbalanced dt/dd set, so the description list is not correctly built from <dl>/<dt>/<dd>, which is step 2 of 9.3.3. Each such failure is also a content-model nesting error that the Nu checker reports under 8.2.1 ('imbrication des balises'). 8.2.1 is secondary and can be dropped if 8.2 is kept for validator output only.", outsideCorrespondence: {"8.2.1":"RGAA relates 8.2 to WCAG 4.1.1 and 4.1.2; the engine files this rule under another criterion because WCAG 2.2 removed 4.1.1 (Parsing). A child of <dl> that is not a dt/dd group breaks 8.2.1's condition \"L’imbrication des balises est conforme\"."} },
    "deprecated-elements-not-used": { tests: ["8.2.1","10.1.1"], note: "Fails obsolete presentational elements (<marquee>, <blink>, <center>, <font> and the like). They are presentation tags 10.1.1 lists (other RGAA tools flag them there) and obsolete elements the Nu checker reports as errors under 8.2.1. Not mapped to 13.8.1/13.8.2: the rule fires on every obsolete element, and even a <marquee> that can be paused passes 13.8.1, so moving or blinking content is left to the auditor.", outsideCorrespondence: {"8.2.1":"RGAA relates 8.2 to WCAG 4.1.1 and 4.1.2; the engine files this rule under another criterion because WCAG 2.2 removed 4.1.1 (Parsing). Obsolete elements break 8.2.1's condition that tags follow the writing rules, and the Nu checker reports them as errors.","10.1.1":"RGAA relates 10.1 to WCAG 1.3.1; the engine files this rule under the criterion for moving content. The elements it fails (marquee, blink, center, font...) are presentation tags, which 10.1.1 step 1 lists."} },
    "dialog-name-present": { tests: ["7.1.1"], note: "Checks that role=dialog/alertdialog has a name from aria-label, aria-labelledby or title. A dialog is a script-driven interface component, and 7.1.1 step 2 requires it to have an explicit name. No other RGAA test covers dialog naming. Medium because 7.1.1 can still pass through an accessible alternative." },
    "dir-attribute-valid": { tests: ["8.10.2"], note: "Fails a dir attribute whose value is not rtl or ltr, which is the first condition of 8.10.2 (\"La valeur de l’attribut dir est conforme (rtl ou ltr)\"). dir=\"auto\", valid HTML, fails too, since RGAA names only the two values. Whether the direction is right for the text (the second condition) needs a human." },
    "dlitem-parent-valid": { tests: ["8.2.1","9.3.3"], note: "Fails a <dt>/<dd> that is not inside a <dl> (directly or via one div), so a description list is not structured with <dl>, <dt> and <dd> (9.3.3 step 2). An orphan dt/dd is also an invalid nesting that the validator reports under 8.2.1 (secondary).", outsideCorrespondence: {"8.2.1":"RGAA relates 8.2 to WCAG 4.1.1 and 4.1.2; the engine files this rule under another criterion because WCAG 2.2 removed 4.1.1 (Parsing). A <dt> or <dd> outside <dl> breaks 8.2.1's condition \"L’imbrication des balises est conforme\"."} },
    "doctype-present": { tests: ["8.1.1","8.1.2","8.1.3"], note: "Fails a page with no doctype (8.1.1), or with one that is neither the HTML5 doctype nor a W3C recommended one (8.1.2). A doctype written after <html> is dropped by the HTML parser, so it fails as missing, which is the case 8.1.3 describes." },
    "duplicate-id": { tests: ["8.2.1"], note: "Fails on non-empty id values that are not unique in their document or shadow tree. That is the 8.2.1 condition 'Les valeurs d'attribut id sont uniques dans la page'." },
    "duplicate-id-aria": { tests: ["8.2.1"], note: "Flags duplicate id values that ARIA ID-reference attributes point to. 8.2.1 step 2 explicitly requires id values to be unique in the page. The rule covers only the referenced subset of ids." },
    "embed-text-alternative-present": { tests: ["1.1.7"], note: "Fails an <embed> with no aria-label/aria-labelledby/title, which covers the text-alternative step of 1.1.7 (step 3). Partial: the rule applies to every <embed>, while 1.1.7 only covers type=\"image/...\". It also does not check role=\"img\" or the adjacent-link/replacement options." },
    "embed-text-alternative-quality": { tests: ["1.3.5"], note: "Asks a human to judge the relevance of an <embed>'s existing name, which is 1.3.5 step 2. Scope mismatch: 1.3.5 only covers image embeds (type=\"image/...\"), and the rule reviews all embeds." },
    "empty-heading": { tests: ["9.1.2"], note: "Flags <h1>-<h6>/role=\"heading\" elements with an empty accessible name. An empty heading cannot have relevant content, which is what 9.1.2 step 1 checks for each heading found in 9.1.1." },
    "empty-table-header": { tests: [], note: "Flags th/columnheader/rowheader cells with no visible text. RGAA 5.6 checks that headers are declared with th or a header role, and 5.7 checks how cells are associated with them. No RGAA test covers the content or relevance of a header cell." },
    "fake-list": { tests: ["9.3.1","9.3.2"], note: "Asks whether lines or consecutive paragraphs that start with the same bullet (9.3.1) or with consecutive numbers (9.3.2) are a list, which those tests want marked up with <ul>/<ol> and <li>, or role=\"list\" and role=\"listitem\". Lists drawn with images or CSS alone are not found." },
    "field-group-legend": { tests: ["11.6.1"], note: "Asks about a <fieldset> or role=\"group\" holding form fields that has no legend (a <legend>, aria-label, aria-labelledby, or title for role=\"group\"). 11.6.1 requires a legend on each grouping of fields of the same kind; whether this group is one is left to a person." },
    "figure-caption-structure": { tests: ["1.9.1"], note: "For a <figure> holding an image and a <figcaption> with text, fails when the figure has no role=\"figure\" or role=\"group\", or no aria-label identical to the caption: conditions 2 and 3 of 1.9.1. Conditions 1 and 4 (figure and figcaption) are what make the rule apply, so a caption given another way is not found." },
    "focus-order-semantics": { tests: [], note: "Flags elements with tabindex>=0 and a non-interactive explicit role (heading, list, region...). When such an element is a scripted control, 7.1.1 step 2 (role consistent with its use) directly applies. Legitimately focusable elements such as scrollable regions make this only partial evidence. Not mapped to 7.1.1: only evidence when the element is a scripted component. Not mapped to 12.8.1 (where other RGAA tools put this check): 12.8.1 checks that the tab order is coherent, not the role of what receives focus." },
    "form-control-label-quality": { tests: ["11.2.1","11.2.4"], note: "Takes the visible label text of a field, from a native <label> or from aria-labelledby references, and flags placeholder labels or duplicate labels with no visible context telling the fields apart. That covers 11.2.1 (the <label> content is relevant) and 11.2.4 (aria-labelledby text is relevant). aria-label and title are not used, so 11.2.2 and 11.2.3 are not covered." },
    "form-control-programmatic-label-present": { tests: ["11.1.1"], note: "Fails input/select/textarea controls (not hidden/submit/reset/button/image) that have no associated <label>, aria-labelledby, aria-label, title or placeholder. A failure means none of the 11.1.1 step-2 conditions hold. Caveat: the rule accepts placeholder, which RGAA 11.1.1 does not, so a pass is not an 11.1.1 pass." },
    "form-control-programmatic-label-quality": { tests: ["11.1.1","11.1.3","11.2.2"], note: "Asks for review of native input/select/textarea controls named only by placeholder or title. A placeholder-only name matches none of the conditions in 11.1.1 step 2. A title-only label is a non-visible label: 11.1.3 step 2 asks whether that title (or adjacent visible text) makes the expected input understandable, and 11.2.2 whether the title is relevant (other RGAA tools review title-labelled fields there).", outsideCorrespondence: {"11.2.2":"RGAA relates 11.2 to WCAG 1.3.1, 2.4.6, 2.5.3 and 3.3.2, while the engine files this rule under 4.1.2. A title-only field is the population of 11.2.2 step 1 (fields labelled by a title attribute), which other RGAA tools review there."} },
    "form-control-single-label": { tests: [], note: "Fails when two or more non-empty <label> elements compete for one control. No RGAA test forbids multiple labels. 11.1.1 (a label exists) and 11.1.2 (for/id match) are met in that case, and 11.2.1 judges each label's wording, not how many labels there are; multiple labels are also valid HTML, so 8.2.1 does not apply." },
    "heading-order": { tests: ["9.1.1"], note: "Flags heading levels that jump by more than one (hx and role=heading/aria-level). This is direct input to 9.1.1 step 2, whether the heading hierarchy is relevant. RGAA does not treat every skipped level as a failure automatically, hence manual review." },
    "heading-quality": { tests: ["9.1.2"], note: "Flags headings (hx or role=heading) whose accessible name is a placeholder, template slot, filename or URL. That is 9.1.2 step 1: is each heading's content relevant." },
    "html-lang-attr-present": { tests: ["8.3.1","8.4.1"], note: "Fails when lang on <html> is missing or empty (8.3.1 step 2, default language present on <html>) or is not a syntactically valid tag (8.4.1 step 2, 'valide' condition). The rule ignores xml:lang and per-element fallbacks that 8.3.1 also accepts, and it does not judge relevance." },
    "html-xml-lang-mismatch": { tests: ["8.2.1","8.4.1"], note: "Fails when lang and xml:lang on <html> declare different primary languages, so at least one of them does not give the document's main language (8.4.1 'pertinent'). The HTML spec also requires the two to be the same value when both are present, which the Nu checker used in 8.2.1 reports. Not mapped to 8.3.1 (where other RGAA tools put this check): the rule only applies when both attributes are present, so a language is always indicated.", outsideCorrespondence: {"8.2.1":"RGAA relates 8.2 to WCAG 4.1.1 and 4.1.2; the engine files this rule under another criterion because WCAG 2.2 removed 4.1.1 (Parsing). HTML requires lang and xml:lang on the same element to match; a mismatch is a validator error under 8.2.1."} },
    "identical-iframes-same-purpose": { tests: ["2.2.1"], note: "Flags iframe/frame elements that share an accessible name but embed different resources, which is evidence that the name does not accurately describe at least one frame. That is the relevance check in 2.2.1 step 2. 2.2.1 covers only the title attribute, so a name coming from aria-label is outside its scope." },
    "identical-links-same-purpose": { tests: [], note: "Asks whether links with the same name but different destinations serve the same purpose (WCAG 2.4.9 AAA, which RGAA does not cover). RGAA 6.1.x accepts context as a way to make a link explicit, so two same-named links with different targets are not direct evidence that either one fails 6.1.1 to 6.1.3." },
    "iframe-focusable-content": { tests: [], note: "Fails same-origin iframes with tabindex=-1 that contain focusable content (inconsistent keyboard reachability). No candidate fits: 7.3 is about elements with script handlers, 4.11/4.12 about media, 10.14/12.11 about extra content shown on hover or focus, and 12.9 about keyboard traps. RGAA has no general 'reachable by Tab' test for frame content." },
    "iframe-name-present": { tests: ["2.1.1"], note: "Flags iframe/frame elements with no name from aria-labelledby, aria-label or title. A frame with no name has no title, so it fails 2.1.1 step 2 (the frame has a title attribute). Coverage is partial: the rule skips tabindex=-1 frames, and accepts aria-label where 2.1.1 requires title specifically." },
    "iframe-title-unique": { tests: ["2.2.1"], note: "Flags frames that share the same title attribute. A shared title usually cannot identify each frame's content, which is what 2.2.1 step 2 (title relevance) checks. Medium because two frames embedding the same content may legitimately share a relevant title." },
    "image-alt-long": { tests: ["1.3.9"], note: "Asks about an image whose text alternative (alt, or aria-label on role=\"img\") is longer than 80 characters, for 1.3.9 (short and concise, particular cases aside). RGAA gives no number; 80 is a threshold for asking." },
    "image-redundant-alt": { tests: ["1.3.1"], note: "Flags <img> whose non-empty alt equals the visible text in its parent. The question is either whether the alternative is relevant (1.3.1 step 2) or whether the image is really decorative and should have alt=\"\" (1.2.1). Both tests cover the same <img> element. Not mapped to 1.2.1: a redundant alt is not evidence that a decorative image is wrongly exposed." },
    "img-alt-decorative": { tests: ["1.1.1","1.1.5","1.1.8"], note: "Asks whether an <img>, <svg> or <canvas> left out of the accessibility tree (alt=\"\", aria-hidden, role none/presentation, unlabeled svg/canvas) is really decorative. That is step 2 (does the image carry information?) of 1.1.1, 1.1.5 and 1.1.8, and a 'no' means an informative image with no alternative. It does not check the 1.2.x conditions for correctly ignoring decorative images." },
    "img-alt-present": { tests: ["1.1.1","1.2.1"], note: "Fails an exposed <img> (not hidden, not a non-focusable role none/presentation) that has no alt, no ARIA name and no title. If the image is informative, that fails 1.1.1 step 3. If it is decorative, it lacks the alt=\"\" / aria-hidden / role=presentation that 1.2.1 step 2 requires." },
    "img-alt-quality": { tests: ["1.3.1"], note: "Asks a human to judge the relevance of a non-empty <img> alt, which is 1.3.1 step 2." },
    "input-image-alt-decorative": { tests: ["1.3.3"], note: "Flags an <input type=\"image\"> whose alt is empty but which is named by aria-label, aria-labelledby or title. RGAA has no decorative image button: 1.1.3 requires every one to have a text alternative, and here one exists, so the question left is whether that name is relevant, which is 1.3.3 (\"S’il est présent, le contenu de l’attribut WAI-ARIA aria-label est pertinent\", and the same for title and aria-labelledby)." },
    "input-image-alt-present": { tests: ["1.1.3"], note: "Fails an image button with no ARIA name, no non-empty alt and no title (or only the browser's default name), which is the presence check of 1.1.3 step 3." },
    "input-image-alt-quality": { tests: ["1.3.3"], note: "Asks a human to judge the relevance of an image button's non-empty alt, which is 1.3.3 step 2." },
    "label-for-target-valid": { tests: ["11.1.2"], note: "Fails a <label for> whose value is empty, matches no id in the label's tree, or matches an element that cannot be labelled: then the field it names has no id equal to the for value, the condition 11.1.2 step 2 checks." },
    "label-in-name": { tests: ["6.1.5","11.2.5","11.9.2","7.1.3"], note: "For controls with aria-label/aria-labelledby and a visible label, checks that the accessible name contains the visible text. By element: links map to 6.1.5, form fields (input, select, textarea and field roles) to 11.2.5, buttons to 11.9.2, and custom widget roles (tab, menuitem, option, treeitem, gridcell) to 7.1.3 step 2 (the name contains the visible label). title-based names, also in those tests, are not checked." },
    "label-title-only": { tests: ["11.1.3","11.2.2"], note: "Flags form fields whose only label is the title attribute, a label that is not visible. 11.1.3 covers fields whose label is not visible, and its first condition accepts a title \"dont le contenu permet de comprendre la nature de la saisie attendue\"; 11.2.2 asks whether each title \"permet de connaître la fonction exacte du champ\". The reviewer answers both from the flagged field." },
    "landmark-banner-is-top-level": { tests: [], note: "Checks that the banner landmark is not nested inside another landmark. Neither 9.2.1 (header structured with <header>) nor 12.6.1 (the zone has a matching landmark or another way to reach or skip it) checks landmark nesting." },
    "landmark-complementary-is-top-level": { tests: [], note: "Checks that complementary/<aside> is not nested inside another landmark. RGAA has no requirement about complementary landmarks or their nesting (9.2.1 and 12.6.1 do not cover aside)." },
    "landmark-contentinfo-is-top-level": { tests: [], note: "Checks that contentinfo is not nested inside another landmark. 9.2.1 only requires the footer zone to use <footer>, and 12.6.1 only requires a matching landmark or an alternative. Neither checks nesting." },
    "landmark-main-is-top-level": { tests: [], note: "Checks that main is not nested inside another landmark. 9.2.1 requires the main zone to use a single visible <main> but says nothing about where it sits; no RGAA test checks nesting." },
    "landmark-no-duplicate-banner": { tests: [], note: "Checks for more than one banner landmark. 9.2.1 requires the header zone to use <header> but does not require it to be unique (uniqueness is only required for <main>)." },
    "landmark-no-duplicate-contentinfo": { tests: [], note: "Checks for more than one contentinfo landmark. 9.2.1 requires the footer zone to use <footer> but does not require it to be unique (uniqueness is only required for <main>)." },
    "landmark-no-duplicate-main": { tests: ["9.2.1"], note: "Flags more than one main landmark exposed to assistive technology (hidden ones are filtered out through isAccTreeEligible). This covers 9.2.1 step 5 and the condition 'une balise <main> visible unique'. The rule also counts role=\"main\", which 9.2.1 does not mention." },
    "landmark-one-main": { tests: ["9.2.1"], note: "Flags pages with no main landmark, which is evidence for 9.2.1 step 4 (the main content zone is structured with <main>). This is partial: the rule accepts role=\"main\" without a <main> element, which 9.2.1 would still reject." },
    "landmark-unique": { tests: [], note: "Checks that landmarks sharing a role have distinct accessible names. No RGAA test requires landmarks to have names or unique names; 12.6.1 only requires a landmark role matching the zone's nature." },
    "layout-table-no-data-markup": { tests: ["5.8.1"], note: "Fails a table with role=\"presentation\" or role=\"none\" that has a non-empty summary, a <caption>, <th>, <thead>, <tfoot>, a rowheader or columnheader role, or cells with scope, headers or axis. Those are the two conditions of 5.8.1, applied to tables marked as layout. A layout table with no role is not found; deciding which tables are layout tables is 5.3." },
    "letters-spaced-with-spaces": { tests: ["10.1.3"], note: "Asks about four or more single letters in a row separated by spaces, the first condition of 10.1.3 (\"Les espaces ne sont pas utilisées pour séparer les lettres d’un mot\"). Spaces used to simulate tables or columns (the other two conditions) are not looked for." },
    "link-in-text-block": { tests: ["10.6.1"], note: "Fails inline a[href] links in running text that have no underline and no weight or style difference, and whose color contrast with the surrounding text is below 3:1. That is 10.6.1 step 2 (3:1 between link and surrounding text for links shown only by color). It checks only the default state, not the visited/hover/focus states of step 3." },
    "link-name-present": { tests: ["6.2.1"], note: "Fails a[href] and role=link elements with no accessible name at all, so the link has no label in its content either: 6.2.1 step 2 (the content of <a> or role=link contains a label, text or text alternative). A pass is weaker evidence than a fail, since the rule also accepts aria-label, aria-labelledby and title, which 6.2.1 does not count. area[href] is covered by 1.1.2 (area-alt-present), not 6.2.1." },
    "link-name-quality": { tests: ["6.1.1","6.1.2","6.1.3","6.1.4"], note: "Flags a[href], area[href] and role=link elements whose full accessible name, whatever its source (text, img alt, SVG), is a generic phrase or a bare file format with no adjacent context. That is the question 6.1.1 to 6.1.4 step 2 asks per link type: does the name alone or with its context give the link's purpose and destination. Unnamed links are explicitly left out, so 6.2.1 is not covered." },
    "list-children-valid": { tests: ["8.2.1","9.3.1","9.3.2"], note: "Fails a <ul>/<ol> with a direct child that is not an <li>/role=listitem (or script/template), so the list is not structured with ul/li (9.3.1) or ol/li (9.3.2), step 2. Children that are not <li> are also nesting errors under 8.2.1 (secondary).", outsideCorrespondence: {"8.2.1":"RGAA relates 8.2 to WCAG 4.1.1 and 4.1.2; the engine files this rule under another criterion because WCAG 2.2 removed 4.1.1 (Parsing). A child of <ul>/<ol> that is not <li> breaks 8.2.1's condition \"L’imbrication des balises est conforme\"."} },
    "listbox-name-present": { tests: ["11.1.1"], note: "Checks that role=listbox has a name from aria-label, aria-labelledby, title or an associated label, matching the conditions in 11.1.1 step 2 (listbox is an ARIA form-field role, and other RGAA tools use 11.1.1 too). Not mapped to 7.1.1: it passes when an accessible alternative exists, and the problem is already reported under 11.1.1." },
    "listitem-parent-valid": { tests: ["8.2.1","9.3.1","9.3.2"], note: "Fails an <li> whose parent is not <ul>/<ol> or role=list/none/presentation, so items grouped as a list are not structured with a ul/ol container. That is step 2 of 9.3.1 or 9.3.2; the rule cannot tell ordered from unordered, so both apply. An <li> outside ul/ol/menu is also a nesting error under 8.2.1 (secondary).", outsideCorrespondence: {"8.2.1":"RGAA relates 8.2 to WCAG 4.1.1 and 4.1.2; the engine files this rule under another criterion because WCAG 2.2 removed 4.1.1 (Parsing). An <li> outside <ul>, <ol> or <menu> breaks 8.2.1's condition \"L’imbrication des balises est conforme\"."} },
    "manual-review": { tests: ["12.8.1","12.9.1","10.7.1"], note: "Always-on page-level prompt to review by keyboard whether focus can leave every component (12.9.1 step 2), whether tab order is coherent (12.8.1 step 2) and whether the focus indicator is visible (10.7.1). It is a reminder only and gives no finding on any element." },
    "media-alternative-transcript-evidence": { tests: ["4.1.1","4.1.2","4.1.3"], note: "Flags <audio>/<video> with no adjacent or linked transcript found, which is the presence step (step 2) of 4.1.1 (audio only), 4.1.2 (video only) and 4.1.3 (synchronised media). It does not tell these media types apart and ignores the audio-description options of 4.1.2/4.1.3." },
    "menuitem-name-present": { tests: ["7.1.1"], note: "Checks that menuitem, menuitemcheckbox and menuitemradio elements have a non-empty name. These are parts of a script-driven menu component, and 7.1.1 step 2 requires an explicit name. Not a form field, so 11.1 does not apply. Not mapped to 11.9.1 (where other RGAA tools put this check): 11.9.1 covers buttons in a form, not menu items." },
    "meta-refresh-no-exceptions": { tests: [], note: "AAA rule that fails any meta refresh with a positive delay. Not linked to 13.1: a refresh of 20 hours or more without a URL passes 13.1.1 and is no redirect for 13.1.2, yet this rule fails it, and the RGAA rollup for 13.1 would fail with it. meta-refresh-timing-absent carries 13.1.1 and 13.1.2 instead. Gap: a redirect delayed 20 hours or more fails 13.1.2 and no rule reports it for RGAA." },
    "meta-refresh-timing-absent": { tests: ["13.1.1","13.1.2"], note: "Fails the first meta http-equiv=refresh with a delay between 1s and 20h. Without a URL this is a meta refresh under 20 hours (13.1.1 step 2); with a URL it is a redirect that is not immediate (13.1.2). Note that 13.1.2 has no 20-hour exception, so a redirect delayed more than 20h passes this rule but fails 13.1.2." },
    "meta-viewport-large": { tests: [], note: "Flags viewport meta tags with user-scalable=no or maximum-scale<5. user-scalable=no, or maximum-scale below 2, blocks graphic zoom to 200%, which 10.4.2 step 1 checks. Values from 2 up to 5 are only a best practice and do not fail RGAA, so the auditor must check the actual value. Not mapped to 10.4.2: the rule flags anything below 500% zoom; RGAA requires 200%, which meta-viewport-zoom-enabled checks." },
    "meta-viewport-zoom-enabled": { tests: ["10.4.2"], note: "Fails a viewport meta that sets user-scalable=no or maximum-scale below 2, which blocks zoom to 200%. That is evidence against 10.4.2 (enlarging all text to 200% must be possible with graphic zoom). It says nothing about loss of content at 200% (10.4.1), and RGAA's desktop method may not show a mobile-only zoom block." },
    "meter-name-present": { tests: ["11.1.1"], note: "Fails an element with explicit role=\"meter\" that has no author-supplied name. The RGAA glossary counts meter as a form field, so an unnamed one fails 11.1.1. Not mapped to 7.1.1: it passes when an accessible alternative exists, and a meter is not necessarily script-driven.", outsideCorrespondence: {"11.1.1":"RGAA relates 11.1 to WCAG 1.3.1, 2.4.6, 2.5.3, 3.3.2 and 4.1.2, while the engine files this rule under 1.1.1. The RGAA glossary counts meter as a form field, so an unnamed meter has no label, which 11.1.1 checks."} },
    "mouse-only-event-handlers": { tests: ["7.3.1"], note: "Flags elements with inline pointer-only handlers (onmouseover, onmousedown, ondblclick, and so on) and no keyboard or focus handler, and asks whether they work by keyboard. That is 7.3.1 steps 2-3 (an element with a JS event handler must be keyboard-accessible, or have an equivalent). It only sees inline attributes." },
    "nested-interactive-controls-absent": { tests: ["8.2.1"], note: "Flags interactive controls that contain another operable control (for example a button inside a[href]). 8.2.1 step 2 requires tag nesting to conform, and the Nu checker reports interactive content inside a/button and some ARIA-role equivalents. Nesting that uses only ARIA roles is only a validator warning (since Nu 26.8.6), so it is not an 8.2.1 failure. Not mapped to 7.1.1 (where other RGAA tools put this check): native nested controls are not scripted components." },
    "no-autoplay-audio": { tests: ["4.10.1"], note: "Flags unmuted autoplaying <audio>/<video> with no native controls and asks about the 3-second rule and a stop or volume mechanism. That is exactly 4.10.1 step 1." },
    "object-text-alternative-present": { tests: ["1.1.6"], note: "Fails an <object> with no fallback text, no ARIA name and no title, which covers the text-alternative step of 1.1.6 (step 4). Partial: the rule applies to every <object>, while 1.1.6 only covers type=\"image/...\". It also accepts fallback content (not a 1.1.6 option) and does not check role=\"img\" or adjacent alternatives." },
    "object-text-alternative-quality": { tests: ["1.3.4"], note: "Asks a human to judge the relevance of an <object>'s title, ARIA name or fallback content, which is 1.3.4 step 2 (fallback content is explicitly listed there). Scope mismatch: 1.3.4 only covers image objects." },
    "office-document-link": { tests: ["13.3.1"], note: "Lists each link to an office document (.pdf, .doc, .docx, .odt, .rtf, .xls, .xlsx, .ods, .ppt, .pptx, .odp, .epub) for a person to check one of the conditions of 13.3.1: the document is accessible, or an accessible version is offered. Downloads started by script or without such an extension are not found." },
    "optgroup-label-present": { tests: ["11.8.2"], note: "Fails an <optgroup> inside a <select> with no label attribute, which is 11.8.2 step 2. An empty label also fails; RGAA only asks for the attribute, and 11.8.3 (is the label relevant) stays with the auditor." },
    "option-name-present": { tests: ["11.1.1"], note: "Checks that role=option has a non-empty name. The RGAA glossary lists option as a form-field role, so an unnamed option fails 11.1.1 (other RGAA tools use 11.1 too). Not mapped to 7.1.1 (where other RGAA tools put this check): it passes when an accessible alternative exists, and the problem is already reported under 11.1.1." },
    "p-as-heading": { tests: ["9.1.3"], note: "Flags short <p> text that is entirely bold and at least 18px, asking whether it is a visual heading without <hx>/role=heading markup. That is the 9.1.3 question: is each passage that acts as a heading structured with <hx> or role=heading plus aria-level?" },
    "page-has-heading-one": { tests: [], note: "Flags pages with no h1 or role=heading aria-level=1. RGAA does not explicitly require an h1, but a missing top level is evidence the auditor weighs in 9.1.1 step 2 (whether the heading hierarchy is relevant). Not mapped to 9.1.1: RGAA does not require an h1." },
    "page-title-patterns": { tests: ["8.6.1"], note: "Manual signal on the <title> content (generic words like 'Home' or 'Untitled', very short titles, and titles duplicated or templated across crawled pages). This is exactly 8.6.1 step 2: is the title relevant enough to find the page in history or tabs." },
    "page-title-present": { tests: ["8.5.1"], note: "Fails when the <title> element is missing or its text is empty, which is 8.5.1 step 1 (a <title> exists). An empty title is treated as an absent title rather than as a relevance (8.6.1) problem." },
    "password-paste-enabled": { tests: [], note: "Concerns WCAG 3.3.8 Accessible Authentication (WCAG 2.2), which RGAA 4.1.2 does not include. No RGAA test covers paste blocking on authentication fields." },
    "presentation-role-conflict": { tests: ["1.2.1"], note: "Flags role=\"presentation\"/\"none\", and <img alt=\"\">, combined with a global ARIA attribute such as aria-label, or with focusability. On a decorative <img>, that breaks 1.2.1, which requires an empty alt \"et est dépourvue de tout autre attribut permettant de fournir une alternative textuelle\". Findings on elements other than <img> are outside 1.2.1, and title is not checked." },
    "presentational-attributes-absent": { tests: ["10.1.2"], note: "Fails on each HTML element carrying an attribute 10.1.2 step 1 lists, with its exceptions: size allowed on <select>, width and height on <img>, <object>, <embed>, <canvas> and <svg>. SVG and MathML content is not checked, where those attributes are geometry rather than presentation." },
    "presentational-children-focusable-absent": { tests: [], note: "Flags tab stops inside roles with presentational children (button, tab, option...). For native button the Nu checker reports interactive content or a tabindex descendant as a nesting error (8.2.1 step 2). Explicit-role cases are mostly not validator errors, and the effect on AT output (7.1.2) is not directly what the rule tests. Not mapped to 8.2.1: the validator 8.2.1 relies on reports only the native-button case." },
    "presentational-elements-absent": { tests: ["10.1.1"], note: "Fails on each element 10.1.1 step 1 lists (basefont, big, blink, center, font, marquee, s, strike, tt), and on <u> when the doctype is not HTML5 (step 2). Written for RGAA, so it checks exactly that list." },
    "progressbar-name-present": { tests: ["11.1.1"], note: "Fails an element with explicit role=\"progressbar\" that has no author-supplied name. The RGAA glossary counts progressbar as a form field, so an unnamed one fails 11.1.1. Not mapped to 7.1.1: it passes when an accessible alternative exists, and a progressbar is not necessarily script-driven.", outsideCorrespondence: {"11.1.1":"RGAA relates 11.1 to WCAG 1.3.1, 2.4.6, 2.5.3, 3.3.2 and 4.1.2, while the engine files this rule under 1.1.1. The RGAA glossary counts progressbar as a form field, so an unnamed progressbar has no label, which 11.1.1 checks."} },
    "radio-group-present": { tests: ["11.5.1"], note: "Asks about two or more radio buttons with the same name, in the same form, that are not all inside one <fieldset>, role=\"group\" or role=\"radiogroup\", the three ways 11.5.1 accepts. 11.5.1 applies \"si nécessaire\", so a person decides. Custom role=\"radio\" widgets are not checked." },
    "region": { tests: [], note: "Flags content under <body> that is outside any landmark. RGAA does not require all content to be inside landmarks: 12.6.1 accepts alternatives to landmarks for specific zones only, and 9.2.1 covers header/nav/main/footer structure, not leftover content." },
    "role-img-text-alternative-present": { tests: ["1.1.1"], note: "Fails an exposed non-<img> element with role=\"img\" (or graphics-symbol/graphics-document) that has no name, which is 1.1.1 step 4. Partial: it also accepts title and SVG <title>, which step 4 does not list, and the graphics-* roles are outside RGAA's wording." },
    "scope-attr-valid": { tests: ["5.7.2","8.2.1"], note: "Flags scope values other than row/col/rowgroup/colgroup. On a th with an invalid scope, 5.7.2 fails because it requires scope=\"row\" or scope=\"col\". An invalid attribute value is also a validity error under 8.2.1. The rule accepts rowgroup/colgroup, so it covers only part of 5.7.2." },
    "scrollable-region-focusable": { tests: [], note: "Flags containers with overflow auto/scroll that have no focusable descendant and are not focusable themselves (keyboard scrolling). No RGAA test covers keyboard scrolling of a plain CSS scroll region: 7.3 needs a script handler, 10.14/12.11 cover extra content shown on hover, focus or activation, and 12.9 covers keyboard traps." },
    "searchbox-name-present": { tests: ["11.1.1"], note: "Checks that role=searchbox has a name from aria-label, aria-labelledby, title or an associated label, matching the conditions in 11.1.1 step 2 for form fields (other RGAA tools use 11.1.1 too). Not mapped to 7.1.1: it passes when an accessible alternative exists, and the problem is already reported under 11.1.1." },
    "server-side-image-map-absent": { tests: ["1.1.4"], note: "Fails any <img ismap>, which is exactly step 1 of 1.1.4 (find <img> with ismap). 1.1.4 passes if the page also has links giving the same destinations, which this rule does not check, so a failure is a finding to verify, not an RGAA failure. 1.1 is outside the WCAG-derived candidates, but the element and attribute match exactly.", outsideCorrespondence: {"1.1.4":"RGAA files 1.1.4 under WCAG 1.1.1 and the engine files server-side image maps under 2.1.1 (Keyboard), but the rule and the test look for the same thing: 1.1.4 step 1 finds each <img> with ismap."} },
    "skip-link": { tests: ["12.7.1","12.7.2"], note: "Flags 'skip/jump to' links whose #fragment does not resolve to a usable target. A dead skip link means the main zone cannot be skipped, which bears on 12.7.1 (where other RGAA tools report a broken skip link), and it fails 12.7.2's condition that the link works ('Le lien est fonctionnel'). The rule does not check the link's position, visibility or consistency across pages, and a skip link can target zones other than main." },
    "slider-name-present": { tests: ["11.1.1"], note: "Checks that explicit role=slider has a name from aria-label, aria-labelledby, title or an associated label, matching the conditions in 11.1.1 step 2 (slider is an ARIA form-field role, and other RGAA tools use 11.1.1 too). Native input[type=range] without the role is out of the rule's scope. Not mapped to 7.1.1: it passes when an accessible alternative exists, and the problem is already reported under 11.1.1." },
    "spinbutton-name-present": { tests: ["11.1.1"], note: "Checks that role=spinbutton has a name from aria-label, aria-labelledby, title or an associated label, matching the conditions in 11.1.1 step 2 for form fields (other RGAA tools use 11.1.1 too). Not mapped to 7.1.1: it passes when an accessible alternative exists, and the problem is already reported under 11.1.1." },
    "summary-name-present": { tests: [], note: "Flags <summary> elements with an empty name. A native details/summary disclosure is not script-generated, so 7.1.1 does not strictly apply. 11.9.1 covers only buttons inside a form, and no other candidate test concerns disclosure widgets. The auditor may still choose to treat a scripted summary under 7.1.1." },
    "svg-hidden-no-alternative": { tests: ["1.1.5","1.2.4"], note: "Fails an <svg aria-hidden=\"true\"> that carries a text alternative: aria-label, aria-labelledby, a title attribute, or a non-empty <title> or <desc>. As a decorative image it breaks conditions 2 to 4 of 1.2.4. If the alternative means the image carries information, it is hidden from assistive technology and has no role=\"img\", failing 1.1.5. Which of the two applies needs a human." },
    "svg-image-text-alternative-present": { tests: [], note: "Targets SVG <image> child elements. RGAA 1.1.5 covers the <svg> root, and 1.1.1 covers <img> and role=\"img\", so no RGAA test is about naming an inner SVG <image>. It would only matter if that element were given role=\"img\", and role-img-text-alternative-present already covers that case." },
    "svg-text-alternative-present": { tests: ["1.1.5"], note: "Fails an <svg> root that seems meant to convey information but has no <title> text and no aria-label/aria-labelledby, which is 1.1.5 step 5. It does not enforce the role=\"img\" requirement of step 3." },
    "svg-text-alternative-quality": { tests: ["1.3.6"], note: "Asks a human to judge the relevance of an <svg>'s existing title/ARIA name, which is 1.3.6 step 2. It also includes desc-only cases." },
    "tab-name-present": { tests: ["7.1.1"], note: "Checks that role=tab has a non-empty name. A tab is part of a script-driven tab panel component, and 7.1.1 step 2 requires an explicit name. Not a form field." },
    "tabindex": { tests: ["12.8.1"], note: "Flags positive tabindex values, which override the natural focus order. This is direct evidence for 12.8.1 step 2, whether the tab order stays coherent, though a positive tabindex is not a failure by itself." },
    "table-duplicate-name": { tests: ["5.2.1"], note: "Asks (cantTell) about tables whose summary attribute repeats the caption. For a complex data table, a summary that only repeats the title does not explain the table's structure, which is the question of 5.2.1 (is the summary relevant). On a simple table the answer is that 5.2.1 does not apply." },
    "table-fake-caption": { tests: ["5.4.1"], note: "Flags tables with no <caption> whose first row is a single cell above multi-cell rows, asking whether that cell is a visual title not tied to the table. That is 5.4.1 step 2: is the data table's title given by caption, title, aria-label or aria-labelledby? The rule does not check title or aria-label, so the reviewer should look for those." },
    "table-headers-attr-valid": { tests: ["5.7.4","8.2.1"], note: "Fails a td/th whose headers attribute references an id that is missing, points to a non-cell, points to the cell itself, or sits in another table, so headers does not list the ids of the associated headers (5.7.4 step 2, second condition). Such references are also flagged by the Nu checker (8.2.1, secondary).", outsideCorrespondence: {"8.2.1":"RGAA relates 8.2 to WCAG 4.1.1 and 4.1.2; the engine files this rule under another criterion because WCAG 2.2 removed 4.1.1 (Parsing). A headers attribute that names no cell of the table is an invalid attribute value under 8.2.1, which the validator reports."} },
    "table-th-has-data-cells": { tests: [], note: "Fails a table (not role=presentation) that has <th> but no <td> at all. If the auditor judges it a layout table, the <th> use fails 5.8.1 step 2. If it is a data table whose cells are all marked <th>, no RGAA test forbids that (5.6.4 allows th), so the auditor must decide which applies. Not mapped to 5.8.1: only a failure if the auditor judges the table a layout table. Not mapped to 5.7.1 (where other RGAA tools put this check): a table with no <td> says nothing about the id, scope or role that 5.7.1 checks." },
    "target-size-minimum": { tests: [], note: "Checks the 24x24 CSS px target size and spacing exception of WCAG 2.5.8, a WCAG 2.2 criterion RGAA 4.1.2 does not include. No RGAA test measures pointer target size." },
    "td-has-header": { tests: ["5.7.4"], note: "In large tables (4x4 or more, no colspan/rowspan), fails a <td> with no headers attribute and no <th> above it in its column or before it in its row: the data cell is not associated with its headers, which is 5.7.4 (where other RGAA tools put the check too). Not mapped to 5.6.1/5.6.2: a cell without associated headers does not show that the headers were not declared with <th>." },
    "textbox-name-present": { tests: ["11.1.1"], note: "Checks that role=textbox has a name from aria-label, aria-labelledby, title or an associated label, matching the conditions in 11.1.1 step 2 for form fields (other RGAA tools use 11.1.1 too). Not mapped to 7.1.1: it passes when an accessible alternative exists, and the problem is already reported under 11.1.1." },
    "tooltip-name-present": { tests: [], note: "Flags role=tooltip with an empty name, which in practice means an empty tooltip. A tooltip is supplementary content, not an operable component whose name 7.1.1 step 2 evaluates. None of the candidate tests checks tooltip content, so a fit to 7.1.1 would be weak." },
    "treeitem-name-present": { tests: ["7.1.1"], note: "Checks that role=treeitem has a non-empty name. A tree item is part of a script-driven tree component, and 7.1.1 step 2 requires an explicit name." },
    "valid-lang": { tests: ["8.8.1"], note: "Checks that lang on elements other than <html> is a syntactically valid language tag. That is the 'valide' condition of 8.8.1 for language changes; relevance is not checked." },
    "video-caption": { tests: ["4.3.1"], note: "Flags <video> without a <track kind=captions|subtitles>, raising the question of 4.3.1 step 2 (are synchronised captions present?). It accepts kind=\"subtitles\", so it gives no evidence for 4.3.2 (kind=\"captions\" required)." },
    "video-captions-track-kind": { tests: ["4.3.2"], note: "Fails a <video> whose subtitle tracks are all kind=\"subtitles\" (or have no kind, which means subtitles), with none kind=\"captions\". That is 4.3.2 as written. Whether the video is pre-recorded synchronised media, and whether a track carries captions at all, needs a human." },
    "video-poster-text-alternative-present": { tests: [], note: "Checks that a <video poster> has an accessible name. No RGAA 4.1.2 test targets poster images: the theme-1 tests list img/area/input/svg/object/embed/canvas, and the theme-4 tests are about transcripts, captions and AT compatibility of the media player, not naming a <video>." }
  }
};

module.exports = { RGAA_RULE_TESTS };
